const CACHE='suomi-v231-gaeste-trennlinie';
const FILES=['./','./index.html','./style.css?v=180','./fonts/dm-sans-latin-wght-normal.woff2','./fonts/dm-sans-latin-ext-wght-normal.woff2','./fonts/fraunces-latin-standard-normal.woff2','./fonts/fraunces-latin-ext-standard-normal.woff2','./impressum.html','./datenschutz.html','./app.js?v=158','./difficult-words.mjs?v=2','./dialogs.mjs?v=2','./dialogs.json','./translation-feedback.mjs?v=1','./word-lookup.mjs?v=2','./endings-practice.mjs?v=2','./lexicon.json','./learning-insights.mjs','./word-practice.mjs?v=61','./wordsearch.mjs','./wordsearch-ui.mjs?v=64','./auth.js?v=122','./classrooms.js?v=95','./classrooms.css?v=80','./quality-review.js?v=4','./duplicate-candidates.json','./supabase-config.js','./supabase-config.js?v=2','./review-plan.mjs','./learning-path.mjs','./learning-path-data.mjs','./grammar-topics.mjs','./verbs-data.mjs','./verb-examples.mjs?v=1','./verb-practice.mjs','./verbs.css?v=83','./sentences.json','./grammar.json','./icon.svg','./manifest.webmanifest','./games.mjs?v=8','./guest-card.mjs?v=12','./home-extras.mjs?v=9','./daily-mix.mjs?v=3','./endings-progress.mjs?v=1','./guest-intro.mjs?v=5','./themes.mjs?v=6','./games.css?v=3','./games-progress.mjs','./i18n.mjs?v=22','./locales/en.mjs?v=29'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('suomi-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
// Seitenaufrufe werden ohne Query-String und Anker gespeichert (?intro, ?x=1 …),
// sonst legt jede Variante einen eigenen Eintrag an und der Cache wächst unbegrenzt.
const cacheKey=request=>{if(request.mode!=='navigate')return request;const u=new URL(request.url);return new Request(u.origin+u.pathname);};
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;const key=cacheKey(event.request);event.respondWith(fetch(event.request).then(response=>{if(response.ok&&response.type==='basic'&&!response.redirected){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(key,copy)));}return response;}).catch(()=>caches.match(key).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
